int fd; // File Descriptor

// Standard Flags (O_RDONLY, O_WRONLY, O_RDWR)
fd = open("data.txt", O_RDONLY);

// Create or Truncate (Requires mode_t permissions)
mode_t perms = S_IRUSR | S_IWUSR; // 0600
int flags = O_WRONLY | O_CREAT | O_TRUNC;
fd = open("new.log", flags, perms);

// Append mode
fd = open("log.txt", O_WRONLY | O_APPEND);

// Error Check (-1 on failure)
if (fd == -1) {
    // Handle error
}

// Release resource
close(fd);
